import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  // ── Per-user state, synced from the browser on sign-up and on every change. ──
  briefs: defineTable({
    userId: v.string(),
    folioId: v.optional(v.string()),
    brief: v.any(),
    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"]),

  // Ephemeral per-turn output for the hosted dossier interview. Convex actions
  // write cumulative reasoning/text snapshots here while the browser watches
  // the authenticated query; the client removes the row when the turn settles.
  dossierInterviewStreams: defineTable({
    userId: v.string(),
    streamId: v.string(),
    text: v.string(),
    reasoning: v.string(),
    phase: v.union(v.literal("reasoning"), v.literal("answer")),
    status: v.union(
      v.literal("running"),
      v.literal("complete"),
      v.literal("error"),
    ),
    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_streamId", ["userId", "streamId"]),

  folios: defineTable({
    userId: v.string(),
    folios: v.array(v.any()),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  folioContent: defineTable({
    userId: v.string(),
    folioId: v.string(),
    html: v.string(),
    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"]),

  // Personal tokens for the CLI and local MCP server. Only a SHA-256 digest
  // is persisted; the clear-text token is returned once when it is created.
  integrationTokens: defineTable({
    userId: v.string(),
    tokenHash: v.string(),
    prefix: v.string(),
    name: v.string(),
    createdAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_tokenHash", ["tokenHash"]),

  // Uploaded manuscript images. The editor stores the resolved URL in its
  // document while this row preserves ownership and the underlying storage
  // id so files can be looked up and deleted safely.
  images: defineTable({
    ownerId: v.string(),
    folioId: v.string(),
    storageId: v.id("_storage"),
    contentType: v.union(
      v.literal("image/gif"),
      v.literal("image/jpeg"),
      v.literal("image/png"),
      v.literal("image/webp"),
    ),
    size: v.number(),
    createdAt: v.number(),
  })
    .index("by_ownerId", ["ownerId"])
    .index("by_ownerId_folioId", ["ownerId", "folioId"])
    .index("by_storageId", ["storageId"]),

  // ── Per-day writing activity, for the public "days writing" heatmap on
  // the author profile page. Append-only-ish: one row per (userId, day),
  // upserted as the user writes. ──
  writingActivity: defineTable({
    userId: v.string(),
    day: v.string(),
    count: v.number(),
    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_day", ["userId", "day"]),

  customPersonas: defineTable({
    userId: v.string(),
    personas: v.array(v.any()),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  // ── Persona feedback notes — the room's marginalia, persisted per user. ──
  // Stored server-side so a signed-in user can re-read their notes across
  // devices. Brief is denormalized so the panel can render summaries cheaply.
  personaNotes: defineTable({
    userId: v.string(),
    folioId: v.optional(v.string()),
    noteId: v.string(),
    personaId: v.string(),
    personaName: v.string(),
    personaColor: v.string(),
    type: v.union(
      v.literal("encouragement"),
      v.literal("suggestion"),
      v.literal("critique"),
      v.literal("perspective"),
    ),
    feedback: v.string(),
    anchor: v.optional(v.string()),
    briefTitle: v.optional(v.string()),
    createdAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"])
    .index("by_userId_noteId", ["userId", "noteId"]),

  // ── Threaded replies to persona notes, optionally re-prompting the agent. ──
  personaReplies: defineTable({
    userId: v.string(),
    folioId: v.optional(v.string()),
    noteId: v.string(),
    replyId: v.string(),
    author: v.string(),
    authorKind: v.union(v.literal("user"), v.literal("persona")),
    personaId: v.optional(v.string()),
    text: v.string(),
    createdAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"])
    .index("by_userId_noteId", ["userId", "noteId"]),

  // ── Rubric results — one per folio; legacy rows may omit folioId. ──
  rubricResults: defineTable({
    userId: v.string(),
    folioId: v.optional(v.string()),
    result: v.any(),
    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"]),

  // ── Editorial change proposals (editors propose edits to the manuscript). ──
  suggestions: defineTable({
    userId: v.string(),
    folioId: v.optional(v.string()),
    suggestionId: v.string(),
    versionId: v.string(),
    personaId: v.string(),
    personaName: v.string(),
    color: v.string(),
    blockId: v.string(),
    original: v.string(),
    replacement: v.string(),
    rationale: v.string(),
    kind: v.union(v.literal("sentence"), v.literal("paragraph")),
    status: v.union(
      v.literal("open"),
      v.literal("accepted"),
      v.literal("rejected"),
    ),
    createdAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_folioId", ["userId", "folioId"])
    .index("by_userId_suggestionId", ["userId", "suggestionId"]),

  // ── Room settings (tunable assistance) — one per user, latest wins. ──
  roomSettings: defineTable({
    userId: v.string(),
    settings: v.any(),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  // ── Appearance (theme) — one per user, latest wins.
  // Its own table rather than a key inside `roomSettings`: that record is
  // written whole by the personas panel, which knows nothing about themes
  // and would drop the key on every assistance change. `updatedAt` is what
  // decides a local-vs-remote conflict when a second device signs in. ──
  appearance: defineTable({
    userId: v.string(),
    preset: v.string(),
    // Token id -> `#rrggbb`. Validated client-side before it is written into
    // a CSS custom property; stored loosely so adding a themeable token
    // later needs no migration.
    custom: v.optional(v.record(v.string(), v.string())),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  // ── Lix snapshots (existing). ──
  lixBlobs: defineTable({
    userId: v.string(),
    blob: v.bytes(),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  // ── Writer bibliographies — saved sources synced with folio state. ──
  bibliographies: defineTable({
    userId: v.string(),
    entries: v.array(v.any()),
    updatedAt: v.number(),
  }).index("by_userId", ["userId"]),

  // ── Published pieces — public read-by-slug, owner-only writes. ──
  // Each row is a snapshot of a folio at publish time. The slug is the
  // ── Published pieces (post + blog). Same table — kind
  // discriminates. The reader route is /<handle>/<slug> for writers who
  // have claimed a handle, falling back to /p/[slug] for legacy links.
  // The blog stream at /blog only shows "blog" pieces authored by an
  // admin. The ownerId index is for the signed-in user's "my pieces"
  // list; (kind, publishedAt) is for the public blog feed.
  // `ownerHandle` is denormalized at publish time so the reader route
  // can resolve without an extra hop; it's null until the owner has
  // claimed a handle (legacy pieces backfill on next publish). ──
  published: defineTable({
    ownerId: v.string(),
    ownerHandle: v.optional(v.string()),
    slug: v.string(),
    folioId: v.string(),
    kind: v.union(v.literal("post"), v.literal("blog")),
    title: v.string(),
    authorName: v.optional(v.string()),
    briefSummary: v.optional(v.string()),

      return existing._id;
    }
    return await ctx.db.insert("briefs", {
      userId,
      folioId,
      brief,
      updatedAt: now,
    });
  },
});

/* ── Folios (list of pieces) ─────────────────────────────────────── */

export const getFolios = query({
  args: {},
  handler: async (ctx) => {
    const userId = await requireIdentity(ctx);
    return await ctx.db
      .query("folios")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();
  },
});

export const putFolios = mutation({
  args: { folios: v.array(v.any()) },
  handler: async (ctx, { folios }) => {
    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("folios")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();
    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { folios, updatedAt: now });
      return existing._id;
    }
    return await ctx.db.insert("folios", {
      userId,
      folios,
      updatedAt: now,
    });
  },
});

/* ── Folio content (per-piece HTML) ──────────────────────────────── */

export const getFolioContent = query({
  args: { folioId: v.string() },
  handler: async (ctx, { folioId }) => {
    const userId = await requireIdentity(ctx);
    return await ctx.db
      .query("folioContent")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
  },
});

export const listFolioContent = query({
  args: {},
  handler: async (ctx) => {
    const userId = await requireIdentity(ctx);
    return await ctx.db
      .query("folioContent")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .collect();
  },
});

export const putFolioContent = mutation({
  args: { folioId: v.string(), html: v.string() },
  handler: async (ctx, { folioId, html }) => {
    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("folioContent")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { html, updatedAt: now });
      return existing._id;
    }
    return await ctx.db.insert("folioContent", {
      userId,
      folioId,
      html,
      updatedAt: now,
    });
  },
});

export const removeFolioContent = mutation({
  args: { folioId: v.string() },
  handler: async (ctx, { folioId }) => {
    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("folioContent")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
    if (existing) {
      await ctx.db.delete(existing._id);
    }
  },
});

/* ── Custom personas ─────────────────────────────────────────────── */

export const getCustomPersonas = query({
  args: {},
  handler: async (ctx) => {
    const userId = await requireIdentity(ctx);
    return await ctx.db
      .query("customPersonas")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();

    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("appearance")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();
    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { preset, custom, updatedAt: now });
      return existing._id;
    }
    return await ctx.db.insert("appearance", {
      userId,
      preset,
      custom,
      updatedAt: now,
    });
  },
});

/* ── Bulk push / pull ────────────────────────────────────────────── */

/**
 * Push the full local-state payload from the browser to the server.
 * Used on sign-up (when the user has local data and no remote data) and
 * after every subsequent local change (debounced).
 */
export const pushAll = mutation({
  args: {
    briefs: v.optional(
      v.array(v.object({ folioId: v.string(), brief: v.any() })),
    ),
    folios: v.optional(v.array(v.any())),
    folioContent: v.optional(
      v.array(v.object({ folioId: v.string(), html: v.string() })),
    ),
    customPersonas: v.optional(v.array(v.any())),
    personaNotes: v.optional(
      v.array(
        v.object({
          folioId: v.string(),
          noteId: v.string(),
          personaId: v.string(),
          personaName: v.string(),
          personaColor: v.string(),
          type: v.string(),
          feedback: v.string(),
          anchor: v.optional(v.string()),
          briefTitle: v.optional(v.string()),
          createdAt: v.number(),
        }),
      ),
    ),
    personaReplies: v.optional(
      v.array(
        v.object({
          folioId: v.string(),
          replyId: v.string(),
          noteId: v.string(),
          author: v.string(),
          authorKind: v.string(),
          personaId: v.optional(v.string()),
          text: v.string(),
          createdAt: v.number(),
        }),
      ),
    ),
    rubricResults: v.optional(
      v.array(v.object({ folioId: v.string(), result: v.any() })),
    ),
    bibliography: v.optional(v.array(v.any())),
  },
  handler: async (ctx, args) => {
    const userId = await requireIdentity(ctx);
    const now = Date.now();

    if (args.briefs) {
      for (const dossier of args.briefs) {
        const existing = await ctx.db
          .query("briefs")
          .withIndex("by_userId_folioId", (q) =>
            q.eq("userId", userId).eq("folioId", dossier.folioId),
          )
          .first();
        if (existing) {
          await ctx.db.patch(existing._id, {
            brief: dossier.brief,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert("briefs", {
            userId,
            folioId: dossier.folioId,
            brief: dossier.brief,
            updatedAt: now,
          });
        }
      }
    }

    if (args.folios !== undefined) {
      const existing = await ctx.db
        .query("folios")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      if (existing) {
        await ctx.db.patch(existing._id, {
          folios: args.folios,
          updatedAt: now,
        });
      } else {
        await ctx.db.insert("folios", {
          userId,
          folios: args.folios,
          updatedAt: now,
        });
      }
    }

    if (args.folioContent) {
      for (const fc of args.folioContent) {
        const existing = await ctx.db
          .query("folioContent")
          .withIndex("by_userId_folioId", (q) =>
            q.eq("userId", userId).eq("folioId", fc.folioId),
          )
          .first();
        if (existing) {
          await ctx.db.patch(existing._id, {
            html: fc.html,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert("folioContent", {
            userId,
            folioId: fc.folioId,
            html: fc.html,
            updatedAt: now,
          });
        }
      }
    }

    if (args.customPersonas !== undefined) {
      const existing = await ctx.db
        .query("customPersonas")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      if (existing) {
        await ctx.db.patch(existing._id, {
          personas: args.customPersonas,
          updatedAt: now,
        });
      } else {
        await ctx.db.insert("customPersonas", {
          userId,
          personas: args.customPersonas,
          updatedAt: now,
        });
      }
    }

    if (args.personaNotes) {
      for (const n of args.personaNotes) {
