      const legacyBrief = loadProjectBrief();
      const folios = await loadFoliosFromIdb();
      const activeFolioId = await loadActiveFolioIdFromIdb();

      // No dossier yet → the writer belongs in onboarding first.
      if (!legacyBrief && folios.length === 0) {
        void nav("/dossier/create/");
        return;
      }

      // Migration: old storage had a single draft. If we have a brief but no
      // folios, create a Folio I from the legacy draft key.
      if (legacyBrief && folios.length === 0) {
        const legacyDraft = loadDraftHtml();
        const draftFolio: Folio = {
          id: crypto.randomUUID(),
          name: legacyBrief.answers.workingTitle || "Current draft",
          type: "draft",
          createdAt: legacyBrief.completedAt,
          updatedAt: Date.now(),
        };
        await saveFoliosToIdb([draftFolio]);
        await saveFolioContentToIdb(draftFolio.id, legacyDraft);
        await saveActiveFolioIdToIdb(draftFolio.id);
        saveDraftHtml(legacyDraft);
        store.folios = [draftFolio];
        store.activeFolioId = draftFolio.id;
        store.editorSeed = legacyDraft;
        await saveProjectBriefForFolio(draftFolio.id, legacyBrief);
        markDirty();
      } else if (folios.length > 0) {
        store.folios = folios;
        store.activeFolioId = activeFolioId ?? folios[0].id;
        store.editorSeed = await loadFolioContentFromIdb(store.activeFolioId);
        saveDraftHtml(store.editorSeed);
      }

      store.brief = await loadProjectBriefForFolio(store.activeFolioId);
      if (store.activeFolioId) {
        await migrateLegacyEditorialArtifacts(store.activeFolioId);
      }
      const folioDossiers = await loadAllBriefsFromIdb();
      if (
        !store.brief &&
        folioDossiers.length === 0 &&
        legacyBrief &&
        store.activeFolioId
      ) {
        await saveProjectBriefForFolio(store.activeFolioId, legacyBrief);
        store.brief = legacyBrief;
      }
      store.hydrated = true;

      // Surface the local-only sign-in nudge unless it was dismissed before.
      const dismissed = await loadMetaFromIdb<boolean>(
        "signin-toast-dismissed",
      );
      store.signInToastDismissed = dismissed === true;

      // Arriving from the landing "Sign in" link → open the auth panel.
      if (new URLSearchParams(window.location.search).get("auth") === "1") {
        accountOpen.value = true;
      }

      // Arriving via a shared-document invite link (?shared=<lixId>).
      const sharedId = new URLSearchParams(window.location.search).get(
        "shared",
      );
      if (sharedId && clientSig.value && auth.value.user) {
        store.joiningShared = true;
        store.joinError = null;
        try {
          const client = clientSig.value;
          // Accept pending invitation for this lixId (no-op if none).
          try {
            await client.mutation(api.collaboration.acceptInvitation, {
              lixId: sharedId,
            });
          } catch {
            // May have already accepted, or no pending invite — that's fine.
          }
          const meta = await client.query(
            api.collaboration.getSharedLixMeta,
            {
              lixId: sharedId,
            },
          );
          if (meta) {
            const { joinSharedLix } = await import(
              "../../utils/collaboration"
            );
            await joinSharedLix(client, sharedId);
            store.sharedLixId = sharedId;
            store.activeFolioId = meta.folioId;
            store.editorSeed = "";
          } else {
            store.joinError = createAppError("PERMISSION_DENIED", {
              source: "convex",
              metadata: { operation: "join-shared-document" },
            });
          }
        } catch (err) {
          reportApplicationDiagnostic(
            "twyne:editor:join-shared-document",
            err,
            { operation: "join-shared-document" },
          );
          store.joinError = normalizeApplicationError(err, {
            source: "convex",
            metadata: { operation: "join-shared-document" },
          });
        } finally {
          store.joiningShared = false;
        }
      }
    } catch (err) {
      reportApplicationDiagnostic("twyne:editor:open-workspace", err, {
        operation: "open-workspace",
      });
      store.workspaceError = normalizeApplicationError(err, {
        source: "application",
        metadata: { operation: "open-workspace" },
      });
      store.hydrated = true;
    }
  })();

  // ── Save editor content to the active folio ──
  const contentHandler = (e: Event) => {
    const html = (e as CustomEvent).detail as string;
    saveDraftHtml(html);
    if (store.activeFolioId) {
      void saveFolioContentToIdb(store.activeFolioId, html);
      const idx = store.folios.findIndex((f) => f.id === store.activeFolioId);
      if (idx >= 0) {
        store.folios[idx].updatedAt = Date.now();
        void saveFoliosToIdb(store.folios);
      }
      markDirty();
    }
  };
  window.addEventListener("twyne:content", contentHandler);
  cleanup(() => window.removeEventListener("twyne:content", contentHandler));

  // ── Persist layout (width, margin, running header, page numbers) ──
  const layoutHandler = (e: Event) => {
    const next = (e as CustomEvent).detail;
    if (!next || !store.activeFolioId) return;
    const idx = store.folios.findIndex((f) => f.id === store.activeFolioId);
    if (idx < 0) return;
    store.folios[idx] = {
      ...store.folios[idx],
      layout: next,
      updatedAt: Date.now(),
    };
    void saveFoliosToIdb(store.folios);
    markDirty();
  };
  window.addEventListener("twyne:layout", layoutHandler);
  cleanup(() => window.removeEventListener("twyne:layout", layoutHandler));

  // ── Persist editable running header / footer text ──
  const headerHandler = (e: Event) => {
    const text = (e as CustomEvent).detail as string;
    if (!store.activeFolioId) return;
    const idx = store.folios.findIndex((f) => f.id === store.activeFolioId);
    if (idx < 0) return;
    store.folios[idx] = {
      ...store.folios[idx],
      header: text,
      updatedAt: Date.now(),
    };
    void saveFoliosToIdb(store.folios);
    markDirty();
  };
  const footerHandler = (e: Event) => {
    const text = (e as CustomEvent).detail as string;
    if (!store.activeFolioId) return;
    const idx = store.folios.findIndex((f) => f.id === store.activeFolioId);
    if (idx < 0) return;
    store.folios[idx] = {
      ...store.folios[idx],
      footer: text,
      updatedAt: Date.now(),
    };
    void saveFoliosToIdb(store.folios);
    markDirty();
  };
  window.addEventListener("twyne:header", headerHandler);
  window.addEventListener("twyne:footer", footerHandler);
  cleanup(() => window.removeEventListener("twyne:header", headerHandler));
  cleanup(() => window.removeEventListener("twyne:footer", footerHandler));

  // Zen mode: collapse both side panels to give the manuscript the full
  // width, and put them back the way they were on exit.
  const zenModeHandler = (e: Event) => {
    const on = !!(e as CustomEvent).detail?.on;
    store.zenActive = on;
    if (on) {
      if (store.panelsBeforeZen) return;
      store.panelsBeforeZen = {

        noteId: r.noteId,
        author: r.author,
        authorKind: r.authorKind,
        personaId: r.personaId,
        text: r.text,
        createdAt: r.timestamp,
      })),
      rubricResults: snap.rubricResults,
      bibliography: snap.bibliography,
    });
    // Success: clear the error and stamp the synced time.
    state.lastSyncedAt = Date.now();
    state.lastErrorAt = null;
    state.lastErrorMessage = null;
  } catch (err) {
    setSyncFailure(err, "push-all");
  } finally {
    state.pushing = false;
    notifyStatusChange();
  }
}

/**
 * Wire the navigator's online/offline events to the sync
 * indicator. Idempotent — calling this twice has the same
 * effect as calling it once.
 */
let _networkListenersBound = false;
export function bindNetworkStatusEvents(): void {
  if (_networkListenersBound) return;
  if (typeof window === "undefined") return;
  _networkListenersBound = true;
  window.addEventListener("online", notifyStatusChange);
  window.addEventListener("offline", notifyStatusChange);
}

async function handleUserChanged(
  previousUserId: string | null,
  newUserId: string,
): Promise<void> {
  if (typeof window === "undefined") return;
  if (!state.client) return;

  // Always start by building a fresh local snapshot — that's what we'll
  // push if the server is empty.
  const local = await buildLocalSnapshot();
  state.lastSnapshot = local;

  // Read the flag before we do anything else. The flag is set on first
  // push of local data, so subsequent sign-ins know not to push again.
  const didSignUpHere =
    window.localStorage.getItem(SIGN_UP_PUSH_FLAG) === newUserId;

  let remote: SyncedSnapshot | null = null;
  try {
    remote = (await state.client.query(api.sync.pullAll, {})) as SyncedSnapshot;
  } catch (err) {
    setSyncFailure(err, "pull-all");
    notifyStatusChange();
    return;
  }

  if (!remote) {
    // Push whatever we have locally; this is the sign-up path.
    await pushLocalSnapshot();
    window.localStorage.setItem(SIGN_UP_PUSH_FLAG, newUserId);
    state.hydratedFromRemote = true;
    return;
  }

  // Merge: for each top-level slice, take whichever side is newer by
  // `updatedAt`. Newer-wins is the simplest sane policy without a CRDT.
  const hasRemoteData =
    remote.briefs.length > 0 ||
    remote.legacyBrief !== null ||
    remote.folios.length > 0 ||
    remote.folioContent.length > 0 ||
    remote.customPersonas !== null ||
    remote.personaNotes.length > 0 ||
    remote.personaReplies.length > 0 ||
    remote.rubricResults.length > 0 ||
    (remote.bibliography?.length ?? 0) > 0;

  if (!hasRemoteData && !didSignUpHere) {
    // Empty account — push what we have to seed it.
    await pushLocalSnapshot();
    window.localStorage.setItem(SIGN_UP_PUSH_FLAG, newUserId);
    state.hydratedFromRemote = true;
    return;
  }

  if (hasRemoteData) {
    await mergeFromRemote(local, remote);
  }

  state.hydratedFromRemote = true;
  // After hydration, push any local deltas back up.
  void pushLocalSnapshot();
}

function setSyncFailure(error: unknown, operation: string): void {
  reportApplicationDiagnostic(`twyne:sync:${operation}`, error, {
    operation,
  });
  const normalized = normalizeApplicationError(error, {
    source: "convex",
    metadata: { operation },
  });
  state.lastErrorAt = Date.now();
  state.lastErrorMessage = `${normalized.message} Your local work remains safe on this device.`;
}

async function mergeFromRemote(
  local: LocalSnapshot,
  remote: SyncedSnapshot,
): Promise<void> {
  // Dossiers — per-folio, newer-wins by the brief's updatedAt.
  for (const dossier of remote.briefs) {
    const localDossier = local.briefs.find(
      (candidate) => candidate.folioId === dossier.folioId,
    );
    if (
      !localDossier ||
      dossier.updatedAt > (localDossier.brief.updatedAt ?? 0)
    ) {
      await saveBriefToIdb(dossier.folioId, dossier.brief);
      await writeFileAsJson(
        `/folios/${dossier.folioId}/brief.json`,
        dossier.brief,
      );
    }
  }
  if (remote.briefs.length === 0 && remote.legacyBrief) {
    const activeFolioId = await loadActiveFolioIdFromIdb();
    const targetFolioId = activeFolioId ?? local.folios[0]?.id;
    const alreadyFiled = targetFolioId
      ? local.briefs.find((candidate) => candidate.folioId === targetFolioId)
      : null;
    if (
      targetFolioId &&
      (!alreadyFiled ||
        remote.legacyBriefUpdatedAt > (alreadyFiled.brief.updatedAt ?? 0))
    ) {
      await saveBriefToIdb(targetFolioId, remote.legacyBrief);
      await writeFileAsJson(
        `/folios/${targetFolioId}/brief.json`,
        remote.legacyBrief,
      );
    }
  }

  // Folios — newer-wins.
  if (remote.foliosUpdatedAt > lastFoliosUpdate(local.folios)) {
    await saveFoliosToIdb(remote.folios);
  }

  // Folio content — per-folio, newer-wins.
  for (const fc of remote.folioContent) {
    const localEntry = local.folioContent.find((l) => l.folioId === fc.folioId);
    if (!localEntry || fc.updatedAt > localEntry.updatedAt) {
      await saveFolioContentToIdb(fc.folioId, fc.html);

