/**
 * Per-user sync functions. Every mutation and query is auth-gated to
 * the calling user — the server-side identity is the source of truth,
 * never an argument. This is the contract the Convex AI guidelines
 * require: "NEVER accept a userId or any user identifier as a function
 * argument for authorization purposes."
 *
 * The functions cover everything the browser used to keep in IndexedDB:
 *   • briefs         — project dossier
 *   • folios         — list of pieces
 *   • folioContent   — per-folio manuscript HTML
 *   • customPersonas — user-edited editorial board
 *   • personaNotes   — the room's marginalia
 *   • personaReplies — threaded reply chains on each note
 *   • rubricResults  — latest galley-proof result
 *   • bibliographies — saved citation/source entries
 *
 * For each table, a `getX` (read latest) and `putX` (upsert) is exposed.
 * `pullAll` and `pushAll` are bulk convenience wrappers used on sign-in
 * and sign-up to hydrate or seed the server in one round-trip.
 */

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

/* ── Identity helpers ───────────────────────────────────────────── */

async function requireIdentity(ctx: {
  auth: { getUserIdentity: () => Promise<{ tokenIdentifier: string } | null> };
}): Promise<string> {
  const id = await ctx.auth.getUserIdentity();
  if (!id) throw new Error("Not signed in");
  return id.tokenIdentifier;
}

/* ── Briefs ──────────────────────────────────────────────────────── */

export const getBrief = query({
  args: { folioId: v.optional(v.string()) },
  handler: async (ctx, { folioId }) => {
    const userId = await requireIdentity(ctx);
    if (folioId) {
      return await ctx.db
        .query("briefs")
        .withIndex("by_userId_folioId", (q) =>
          q.eq("userId", userId).eq("folioId", folioId),
        )
        .first();
    }
    return await ctx.db
      .query("briefs")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();
  },
});

export const putBrief = mutation({
  args: { folioId: v.string(), brief: v.any() },
  handler: async (ctx, { folioId, brief }) => {
    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("briefs")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { brief, updatedAt: now });
      return existing._id;
    }
    return await ctx.db.insert("briefs", {
      userId,
      folioId,
      brief,
      updatedAt: now,
    });
  },
});

import { api } from "../../convex/_generated/api";
import type { ConvexClient } from "convex/browser";
import type {
  Folio,
  Persona,
  PersonaFeedback,
  RubricResult,
  ProjectBrief,
  PersonaReply,
  Suggestion,
  RoomSettings,
} from "../types";
import { DEFAULT_ROOM_SETTINGS } from "../types";
import type { BibEntry } from "./bibliography";
import {
  loadDraftHtmlFromIdb,
  loadFoliosFromIdb,
  loadPersonasFromIdb,
  loadFolioContentFromIdb,
  loadFolioContentSnapshotFromIdb,
  loadActiveFolioIdFromIdb,
  loadAllBriefsFromIdb,
  saveFoliosToIdb,
  saveBriefToIdb,
  saveFolioContentToIdb,
  savePersonasToIdb,
  saveDraftHtmlToIdb,
  loadRubricResultFromIdb,
  saveRubricResultToIdb,
  clearIdbStore,
} from "./idb";
import { persistToIdb, readFileAsJson, writeFileAsJson } from "./lix";
import { normalizeApplicationError } from "./application-errors";
import { reportApplicationDiagnostic } from "./application-diagnostics";

/**
 * Browser ↔ Convex sync for the per-user data. The local IndexedDB
 * remains the source of truth for the current session; the server is
 * the source of truth across sessions and devices.
 *
 * The orchestrator tracks the current `userId` and runs the right
 * migration when it changes:
 *
 *   userId  null →  X  (sign-up)   : push everything local to the server
 *   userId  X  →  null (sign-out)  : keep local state, clear server ctx
 *   userId  X  →  Y  (account swap): if Y has remote data, pull it; else
 *                                    push X's local data to Y
 *   userId  same (re-auth)         : no-op (data already synced)
 *
 * Continuous sync is debounced — every time the local state changes,
 * `markDirty()` is called and a single `pushAll` fires at most every
 * 4 seconds. A final flush runs on `pagehide`.
 */

type ConvexSyncClient = Pick<ConvexClient, "query" | "mutation">;

interface SyncedSnapshot {
  briefs: Array<{
    folioId: string;
    brief: ProjectBrief;
    updatedAt: number;
  }>;
  /** One-row-per-user dossier written before briefs became folio-scoped. */
  legacyBrief: ProjectBrief | null;
  legacyBriefUpdatedAt: number;
  folios: Folio[];
  foliosUpdatedAt: number;
  folioContent: Array<{ folioId: string; html: string; updatedAt: number }>;
  customPersonas: Persona[] | null;
  customPersonasUpdatedAt: number;
  personaNotes: Array<{
    folioId?: string;
    noteId: string;
    personaId: string;
    personaName: string;
    personaColor: string;
    type: "encouragement" | "suggestion" | "critique" | "perspective";
    feedback: string;
    anchor?: string;
    briefTitle?: string;
    createdAt: number;
  }>;
  personaReplies: Array<{
    folioId?: string;
    replyId: string;
    noteId: string;
    author: string;
    authorKind: "user" | "persona";
    personaId?: string;
    text: string;
    createdAt: number;
  }>;
  rubricResults: Array<{
    folioId?: string;
    result: RubricResult;
    updatedAt: number;
  }>;
  bibliography: BibEntry[];
  bibliographyUpdatedAt: number;
}

  aiSettings: null,
  aiEnhanceCitations: false,
  autoFormatting: false,
  formattingIds: {},
  addedIds: {},
});

const autoFormatIfEnabled = $(async (citations: DetectedCitation[]) => {
  if (
    store.autoFormatting ||
    !activeFolio ||
    !store.aiSettings ||
    !store.aiEnhanceCitations ||
    !hasConfiguredAiProvider(store.aiSettings)
  ) {
    return;
  }
  store.autoFormatting = true;
  try {
    const seen = new Set(
      store.bibliography.map((entry) => entry.url.replace(/\/+$/, "")),
    );
    let all: BibEntry[] | null = null;
    for (const citation of citations.slice(0, 5)) {
      if (
        citation.lookupUrl &&
        seen.has(citation.lookupUrl.replace(/\/+$/, ""))
      ) {
        continue;
      }
      const result = await runClientCitationFormat(
        {
          rawText: citation.text,
          style: store.style,
          context: activeFolio.name,
        },
        store.aiSettings,
      );
      if (!result) continue;
      all = await mergeBibEntry(
        buildBibEntryFromFormattedCitation(
          citation,
          result,
          activeFolio.id,
        ),
      );
      if (citation.lookupUrl) {
        seen.add(citation.lookupUrl.replace(/\/+$/, ""));
      }
    }
    if (all) store.bibliography = all;
  } finally {
    store.autoFormatting = false;
  }
});

const addToBibliography = $(async (citation: DetectedCitation) => {
  if (store.formattingIds[citation.id]) return;
  if (!activeFolio) return;
  store.formattingIds = { ...store.formattingIds, [citation.id]: true };
  try {
    if (store.aiSettings && hasConfiguredAiProvider(store.aiSettings)) {
      const result = await runClientCitationFormat(
        {
          rawText: citation.text,
          style: store.style,
          context: activeFolio.name,
        },
        store.aiSettings,
      );
      if (result) {
        const all = await mergeBibEntry(
          buildBibEntryFromFormattedCitation(
            citation,
            result,
            activeFolio.id,
          ),
        );
        store.bibliography = all;
        store.addedIds = { ...store.addedIds, [citation.id]: true };
        return;
      }
    }
    const all = await mergeBibEntry(
      buildBibEntryFromFormattedCitation(
        citation,
        { title: citation.text, url: citation.lookupUrl },
        activeFolio.id,
      ),
    );
    store.bibliography = all;
    store.addedIds = { ...store.addedIds, [citation.id]: true };
  } finally {
    store.formattingIds = { ...store.formattingIds, [citation.id]: false };
  }
});

